(function () {
  'use strict';

  var maxAniso = renderer.capabilities.getMaxAnisotropy();
  var outEnc = renderer.outputEncoding;

  // deterministic rng so the finish is stable across reloads
  var seed = 1672;
  function rnd() { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; }

  function makeTex(size, draw) {
    var c = document.createElement('canvas');
    c.width = c.height = size;
    draw(c.getContext('2d'), size);
    var t = new THREE.CanvasTexture(c);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = maxAniso;
    if (outEnc && THREE.sRGBEncoding && outEnc === THREE.sRGBEncoding) t.encoding = THREE.sRGBEncoding;
    t.needsUpdate = true;
    return t;
  }

  function applyMap(m, t, colorHex) {
    if (!m) return;
    m.map = t;
    if (colorHex !== undefined) m.color.setHex(colorHex);
    m.needsUpdate = true;
  }

  // ---------- 1) timber floor: 140mm planks, warm oak ----------
  var tTimber = makeTex(512, function (ctx, s) {
    var cols = 4, pw = s / cols;
    for (var i = 0; i < cols; i++) {
      var l = 51 + (rnd() - 0.5) * 8;                 // per-plank +-8% lightness
      ctx.fillStyle = 'hsl(33,32%,' + l + '%)';
      ctx.fillRect(i * pw, 0, pw, s);
      // subtle grain lines
      for (var g = 0; g < 7; g++) {
        var gx = i * pw + 6 + rnd() * (pw - 12);
        ctx.strokeStyle = 'rgba(96,66,36,' + (0.05 + rnd() * 0.06).toFixed(3) + ')';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(gx, 0);
        for (var yy = 0; yy <= s; yy += 64) ctx.lineTo(gx + (rnd() - 0.5) * 5, yy);
        ctx.stroke();
      }
      // staggered end-joint seams (2px darker)
      var y = Math.floor(rnd() * 180);
      while (y < s) {
        ctx.fillStyle = 'hsl(33,34%,' + (l - 16) + '%)';
        ctx.fillRect(i * pw, y, pw, 2);
        y += 190 + Math.floor(rnd() * 160);
      }
      // long seam between planks (2px darker)
      ctx.fillStyle = 'hsl(33,34%,' + (l - 18) + '%)';
      ctx.fillRect(i * pw, 0, 2, s);
    }
  });
  tTimber.repeat.set(26, 40);
  applyMap(M.tFloor, tTimber, 0xf0e8dc);

  // ---------- 600mm porcelain tile ----------
  var tTile = makeTex(512, function (ctx, s) {
    ctx.fillStyle = '#b7b1a6';                        // grout
    ctx.fillRect(0, 0, s, s);
    var n = 2, ts = s / n;
    for (var i = 0; i < n; i++) for (var j = 0; j < n; j++) {
      var l = 82 + (rnd() - 0.5) * 4;
      ctx.fillStyle = 'hsl(38,9%,' + l + '%)';
      ctx.fillRect(i * ts + 1, j * ts + 1, ts - 2, ts - 2);
      for (var k = 0; k < 140; k++) {
        ctx.fillStyle = 'rgba(120,112,100,' + (0.02 + rnd() * 0.04).toFixed(3) + ')';
        ctx.fillRect(i * ts + 2 + rnd() * (ts - 5), j * ts + 2 + rnd() * (ts - 5), 2, 2);
      }
    }
  });
  tTile.repeat.set(10, 16);
  applyMap(M.tile, tTile, 0xffffff);

  // ---------- 300mm wet-area tile, cooler grey-green ----------
  var tWet = makeTex(512, function (ctx, s) {
    ctx.fillStyle = '#8f9a94';                        // grout
    ctx.fillRect(0, 0, s, s);
    var n = 4, ts = s / n;
    for (var i = 0; i < n; i++) for (var j = 0; j < n; j++) {
      var l = 71 + (rnd() - 0.5) * 4;
      ctx.fillStyle = 'hsl(150,7%,' + l + '%)';
      ctx.fillRect(i * ts + 1, j * ts + 1, ts - 2, ts - 2);
      for (var k = 0; k < 50; k++) {
        ctx.fillStyle = 'rgba(90,105,98,' + (0.02 + rnd() * 0.04).toFixed(3) + ')';
        ctx.fillRect(i * ts + 2 + rnd() * (ts - 4), j * ts + 2 + rnd() * (ts - 4), 1, 1);
      }
    }
  });
  tWet.repeat.set(3, 3);
  applyMap(M.wetTile, tWet, 0xffffff);

  // ---------- carpet: fine loop pile, warm grey ----------
  var tCarpet = makeTex(256, function (ctx, s) {
    ctx.fillStyle = 'hsl(35,9%,66%)';
    ctx.fillRect(0, 0, s, s);
    for (var y = 0; y < s; y += 3) {                  // pile rows
      ctx.fillStyle = 'rgba(60,54,46,0.03)';
      ctx.fillRect(0, y, s, 1);
    }
    for (var k = 0; k < 7000; k++) {
      var dark = rnd() < 0.5;
      ctx.fillStyle = dark ? 'rgba(70,62,52,' + (0.04 + rnd() * 0.07).toFixed(3) + ')'
                           : 'rgba(255,250,240,' + (0.04 + rnd() * 0.06).toFixed(3) + ')';
      ctx.fillRect(Math.floor(rnd() * s), Math.floor(rnd() * s), 1, 1);
    }
  });
  tCarpet.repeat.set(12, 12);
  applyMap(M.carpet, tCarpet, 0xffffff);

  // ---------- render wall: near-white subtle acrylic noise, keep material colour ----------
  var tRender = makeTex(256, function (ctx, s) {
    ctx.fillStyle = '#fcfbf9';
    ctx.fillRect(0, 0, s, s);
    for (var k = 0; k < 4200; k++) {
      ctx.fillStyle = 'rgba(70,66,60,' + (0.015 + rnd() * 0.03).toFixed(3) + ')';
      ctx.fillRect(Math.floor(rnd() * s), Math.floor(rnd() * s), 1 + Math.floor(rnd() * 2), 1);
    }
    for (var k2 = 0; k2 < 1800; k2++) {
      ctx.fillStyle = 'rgba(255,255,255,' + (0.03 + rnd() * 0.04).toFixed(3) + ')';
      ctx.fillRect(Math.floor(rnd() * s), Math.floor(rnd() * s), 1, 1);
    }
  });
  tRender.repeat.set(8, 4);
  applyMap(M.render, tRender);                        // keep #cec8c1 colour

  // ---------- kliplock roof: vertical ribs ~430mm, keep surfmist colour ----------
  var tKlip = makeTex(512, function (ctx, s) {
    ctx.fillStyle = '#fdfcf9';
    ctx.fillRect(0, 0, s, s);
    for (var k = 0; k < 60; k++) {                    // faint pan streaks
      var sx = rnd() * s;
      ctx.fillStyle = 'rgba(90,90,84,' + (0.01 + rnd() * 0.02).toFixed(3) + ')';
      ctx.fillRect(sx, 0, 1 + rnd() * 3, s);
    }
    var ribs = 12, step = s / ribs;                   // 12 ribs -> ~430mm each in world
    for (var i = 0; i < ribs; i++) {
      var x = Math.round(i * step);
      ctx.fillStyle = 'rgba(55,57,54,0.20)';
      ctx.fillRect(x, 0, 3, s);                       // rib shadow
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      ctx.fillRect(x + 3, 0, 2, s);                   // rib highlight
      ctx.fillStyle = 'rgba(55,57,54,0.06)';
      ctx.fillRect(x + 5, 0, 4, s);                   // soft falloff
    }
  });
  tKlip.repeat.set(3, 1);                             // 12 ribs * 0.43m * 3 ≈ 15.5m span
  applyMap(M.surfmist, tKlip);                        // keep surfmist colour

  // ---------- lawn: mottled two-green ----------
  if (M.lawn) {
    var tLawn = makeTex(512, function (ctx, s) {
      ctx.fillStyle = '#6c8c4f';
      ctx.fillRect(0, 0, s, s);
      for (var b = 0; b < 320; b++) {
        ctx.fillStyle = (rnd() < 0.5 ? 'rgba(88,122,62,' : 'rgba(122,154,88,') + (0.15 + rnd() * 0.2).toFixed(3) + ')';
        ctx.beginPath();
        ctx.ellipse(rnd() * s, rnd() * s, 8 + rnd() * 34, 6 + rnd() * 26, rnd() * Math.PI, 0, Math.PI * 2);
        ctx.fill();
      }
      for (var k = 0; k < 2600; k++) {
        ctx.fillStyle = rnd() < 0.5 ? 'rgba(52,74,38,0.14)' : 'rgba(150,178,110,0.12)';
        ctx.fillRect(Math.floor(rnd() * s), Math.floor(rnd() * s), 1, 2);
      }
    });
    tLawn.repeat.set(14, 14);
    applyMap(M.lawn, tLawn, 0xffffff);
  }

  // ---------- concrete: light broom finish ----------
  var tConc = makeTex(256, function (ctx, s) {
    ctx.fillStyle = '#d0cdc7';
    ctx.fillRect(0, 0, s, s);
    for (var k = 0; k < 2400; k++) {                  // broom streaks
      var y = Math.floor(rnd() * s), x = Math.floor(rnd() * s), w = 18 + rnd() * 46;
      ctx.fillStyle = rnd() < 0.6 ? 'rgba(96,92,86,' + (0.03 + rnd() * 0.05).toFixed(3) + ')'
                                  : 'rgba(255,252,246,' + (0.03 + rnd() * 0.04).toFixed(3) + ')';
      ctx.fillRect(x, y, w, 1);
    }
    for (var k2 = 0; k2 < 1400; k2++) {
      ctx.fillStyle = 'rgba(80,76,70,' + (0.02 + rnd() * 0.04).toFixed(3) + ')';
      ctx.fillRect(Math.floor(rnd() * s), Math.floor(rnd() * s), 1, 1);
    }
  });
  tConc.repeat.set(8, 8);
  applyMap(M.concrete, tConc, 0xffffff);

  // ---------- 2) lighting ----------
  if (typeof fill !== 'undefined' && fill && fill.intensity !== undefined) fill.intensity += 0.08;

  scene.add(new THREE.AmbientLight(0xfff2e0, 0.12));

  [
    [0, 2.6, -3], [0, 2.6, 6],        // LGF
    [3, 5.9, -6], [0, 5.9, 6],        // GF
    [2, 8.9, 6], [2.5, 8.9, 3.5]      // FF
  ].forEach(function (p) {
    var pl = new THREE.PointLight(0xffe0b3, 0.35, 9);
    pl.position.set(p[0], p[1], p[2]);
    pl.castShadow = false;
    scene.add(pl);
  });

  // ---------- 3) renderer / atmosphere ----------
  renderer.toneMappingExposure = 1.25;
  scene.fog = new THREE.Fog(0x9cc4e0, 120, 320);
})();

