(function () {
  // ---- shared materials (created once) ----
  var trunkMat = mat(0x6b5136, 0.9);
  var leafA = mat(0x5d7a4a, 1.0);
  var leafB = mat(0x4e6b3f, 1.0);
  var soilMat = mat(0x4a3b2e, 1.0);
  var potMat = mat(0x55504a, 0.9);
  var wireMat = mat(0x9a9a9a, 0.4, 0.6);

  function addMesh(mesh, x, y, z) {
    mesh.position.set(x, y, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    house.add(mesh);
    return mesh;
  }
  function cyl(rt, rb, h, m, seg) {
    return new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg || 8), m);
  }
  function sph(r, m, w, hh) {
    return new THREE.Mesh(new THREE.SphereGeometry(r, w || 10, hh || 8), m);
  }
  function shrub(x, z, r, m, yBase) {
    var gy = (yBase !== undefined) ? yBase : groundY(x, z);
    addMesh(sph(r, m), x, gy + r * 0.75, z);
  }

  // ---- 2) TREES around the boundary (9) ----
  // [x, z, trunkR, trunkH, foliageCount]
  var trees = [
    [-7.8, -13.2, 0.16, 2.2, 3],
    [-8.0,  -4.1, 0.14, 1.8, 2],
    [-7.9,   7.2, 0.18, 2.5, 3],
    [ 7.5, -12.4, 0.15, 2.0, 3],
    [ 7.6,  -3.2, 0.13, 1.6, 2],
    [ 7.4,   5.1, 0.17, 2.3, 3],
    [-4.1, -16.9, 0.20, 2.6, 3],
    [ 3.1, -17.1, 0.16, 2.1, 2],
    [ 7.2,  14.2, 0.14, 1.9, 3]
  ];
  for (var ti = 0; ti < trees.length; ti++) {
    var t = trees[ti];
    var tx = t[0], tz = t[1], tr = t[2], th = t[3], nf = t[4];
    var gy = groundY(tx, tz);
    addMesh(cyl(tr * 0.7, tr, th, trunkMat, 8), tx, gy + th / 2, tz);
    var fr = 0.68 + th * 0.28;
    var mA = (ti % 2 === 0) ? leafA : leafB;
    var mB = (ti % 2 === 0) ? leafB : leafA;
    if (ti % 3 === 1) {
      // conifer style: stacked cones
      addMesh(new THREE.Mesh(new THREE.ConeGeometry(fr * 0.85, fr * 1.5, 8), mA), tx, gy + th + fr * 0.55, tz);
      addMesh(new THREE.Mesh(new THREE.ConeGeometry(fr * 0.6, fr * 1.2, 8), mB), tx, gy + th + fr * 1.35, tz);
      if (nf > 2) addMesh(new THREE.Mesh(new THREE.ConeGeometry(fr * 0.38, fr * 0.9, 8), mA), tx, gy + th + fr * 2.0, tz);
    } else {
      // rounded canopy: stacked spheres
      addMesh(sph(fr, mA), tx, gy + th + fr * 0.42, tz);
      addMesh(sph(fr * 0.72, mB), tx + fr * 0.28, gy + th + fr * 1.02, tz - fr * 0.15);
      if (nf > 2) addMesh(sph(fr * 0.5, mA), tx - fr * 0.25, gy + th + fr * 1.5, tz + fr * 0.12);
    }
  }

  // ---- 2) LOW HEDGES along street boundary (split at driveway -5.9..-0.15 and gate 0.5..2.2) ----
  var hedgeSegs = [[-0.1, 0.5], [2.2, 6.0]];
  for (var hi = 0; hi < hedgeSegs.length; hi++) {
    var hs = hedgeSegs[hi];
    var hgy = groundY((hs[0] + hs[1]) / 2, 17.1);
    box(hs[0], hs[1], hgy, hgy + 0.5, 16.9, 17.3, leafB);
  }

  // ---- 2) GARDEN BEDS ----
  // south garden face bed
  var gyg = groundY(3.4, -9.85);
  box(1.0, 5.8, gyg, gyg + 0.16, -10.1, -9.6, soilMat, true);
  shrub(1.6, -9.85, 0.26, leafA, gyg + 0.16);
  shrub(2.9, -9.85, 0.30, leafB, gyg + 0.16);
  shrub(4.2, -9.85, 0.25, leafA, gyg + 0.16);
  shrub(5.5, -9.85, 0.29, leafB, gyg + 0.16);
  // bed beside the pool (west side)
  var gyb = groundY(-5.9, -13.4);
  box(-6.35, -5.45, gyb, gyb + 0.16, -15.3, -11.6, soilMat, true);
  shrub(-5.9, -14.5, 0.30, leafB, gyb + 0.16);
  shrub(-5.9, -13.3, 0.27, leafA, gyb + 0.16);
  shrub(-5.9, -12.1, 0.31, leafB, gyb + 0.16);

  // ---- 2) SUN LOUNGERS (slatted timber, at z ~-12.5) ----
  function lounger(x0) {
    var cgy = groundY(x0 + 0.5, -12.5);
    // 3 slats forming the flat bed (along z)
    for (var s = 0; s < 3; s++) {
      var sx0 = x0 + 0.02 + s * 0.34;
      box(sx0, sx0 + 0.28, cgy + 0.24, cgy + 0.30, -13.25, -11.95, M.timber);
    }
    // angled backrest at north end
    var back = bx(0.94, 0.72, 0.05, M.timber);
    back.rotation.x = 0.55;
    addMesh(back, x0 + 0.5, cgy + 0.52, -11.82);
    // 2 legs
    box(x0 + 0.06, x0 + 0.12, cgy, cgy + 0.24, -13.2, -13.14, M.darkTimber);
    box(x0 + 0.88, x0 + 0.94, cgy, cgy + 0.24, -12.06, -12.0, M.darkTimber);
  }
  lounger(0.2);
  lounger(1.8);

  // ---- 2) POOL FENCE: glass panes + monument posts, gate gap at NE corner ----
  var fy0 = -0.44, fy1 = 0.76;
  var postKeys = {};
  function post(px, pz) {
    var k = Math.round(px * 100) + '_' + Math.round(pz * 100);
    if (postKeys[k]) return;
    postKeys[k] = 1;
    box(px - 0.03, px + 0.03, fy0, fy1 + 0.02, pz - 0.03, pz + 0.03, M.monument);
  }
  function fenceRunX(x0, x1, z) {
    var n = Math.max(1, Math.round((x1 - x0) / 1.6));
    var step = (x1 - x0) / n;
    for (var i = 0; i <= n; i++) post(x0 + i * step, z);
    for (var j = 0; j < n; j++) {
      box(x0 + j * step + 0.05, x0 + (j + 1) * step - 0.05, fy0 + 0.05, fy1 - 0.02, z - 0.01, z + 0.01, M.glass);
    }
  }
  function fenceRunZ(z0, z1, x) {
    var n = Math.max(1, Math.round((z1 - z0) / 1.6));
    var step = (z1 - z0) / n;
    for (var i = 0; i <= n; i++) post(x, z0 + i * step);
    for (var j = 0; j < n; j++) {
      box(x - 0.01, x + 0.01, fy0 + 0.05, fy1 - 0.02, z0 + j * step + 0.05, z0 + (j + 1) * step - 0.05, M.glass);
    }
  }
  fenceRunX(-5.1, -0.9, -16.55);       // south
  fenceRunZ(-16.55, -10.25, -5.1);     // west
  fenceRunZ(-16.55, -10.25, -0.9);     // east
  fenceRunX(-5.1, -1.9, -10.25);       // north, stops at gate gap (-1.9..-0.9 = gate)
  post(-1.9, -10.25);                  // gate-side post

  // ---- 2) STEPPING STONES from alfresco edge toward the pool ----
  for (var si = 0; si < 5; si++) {
    var szz = -9.85 - si * 0.68;
    var sxx = -2.2 + (si % 2 ? 0.12 : -0.1);
    var sgy = groundY(sxx, szz);
    box(sxx - 0.3, sxx + 0.3, sgy + 0.01, sgy + 0.05, szz - 0.225, szz + 0.225, M.concrete, true);
  }

  // ---- 2b) LETTERBOX at the street ----
  var gyl = groundY(1.9, 16.9);
  box(1.78, 2.02, gyl, gyl + 0.85, 16.79, 17.01, M.render);            // plinth
  box(1.70, 2.10, gyl + 0.85, gyl + 1.2, 16.72, 17.08, M.monument);    // box
  box(1.78, 2.02, gyl + 1.02, gyl + 1.06, 17.075, 17.095, M.white, true); // slot (street face)

  // ---- 2b) FEATURE PLANTERS flanking the porch (GF 3.45) ----
  var planters = [[0.2, 12.1], [2.45, 12.1]];
  for (var pi = 0; pi < planters.length; pi++) {
    var px = planters[pi][0], pz = planters[pi][1];
    addMesh(cyl(0.30, 0.23, 0.5, potMat, 12), px, 3.45 + 0.25, pz);
    addMesh(sph(0.32, pi % 2 ? leafB : leafA), px, 3.45 + 0.72, pz);
  }

  // ---- 3) EXTERNAL STAIR: second lower handrail + 3 balusters (east stair) ----
  var ry0 = 0.55, ry1 = 4.0, rz0 = 2.95, rz1 = 7.95;
  var rdy = ry1 - ry0, rdz = rz1 - rz0;
  var rlen = Math.sqrt(rdy * rdy + rdz * rdz);
  var rail = cyl(0.022, 0.022, rlen, M.monument, 8);
  rail.rotation.x = Math.atan2(rdz, rdy);
  addMesh(rail, 7.04, (ry0 + ry1) / 2, (rz0 + rz1) / 2);
  var bts = [0.22, 0.5, 0.78];
  for (var bi = 0; bi < bts.length; bi++) {
    var bt = bts[bi];
    var bz = rz0 + rdz * bt, by = ry0 + rdy * bt;
    addMesh(bx(0.03, 0.6, 0.03, M.monument), 7.04, by + 0.25, bz);
  }

  // ---- 4) CLOTHESLINE (east side, slim frame: 2 posts + crossarms + 3 wires) ----
  var gyc = groundY(6.6, -6.5);
  box(6.575, 6.625, gyc, gyc + 1.22, -7.325, -7.275, M.monument);
  box(6.575, 6.625, gyc, gyc + 1.22, -5.725, -5.675, M.monument);
  box(6.38, 6.82, gyc + 1.16, gyc + 1.20, -7.32, -7.28, M.monument, true);
  box(6.38, 6.82, gyc + 1.16, gyc + 1.20, -5.72, -5.68, M.monument, true);
  var wxs = [6.42, 6.6, 6.78];
  for (var wi = 0; wi < wxs.length; wi++) {
    box(wxs[wi] - 0.006, wxs[wi] + 0.006, gyc + 1.13, gyc + 1.145, -7.28, -5.72, wireMat, true);
  }
})();

