(function () {
  // ---------- shared materials ----------
  var sofaFab = mat(0xb9b2a4, 1);
  var cushFab = mat(0xa79d8c, 1);
  var rugMat  = mat(0xcac2b2, 1);
  var rugMat2 = mat(0xbfb7a6, 1);
  var shadeDk = mat(0x2a2d31, 0.4, 0.3);
  var warmIn  = mat(0xffd9a0, 0.5, 0, { emissive: 0xff9a40, emissiveIntensity: 0.55 });
  var linen   = mat(0xe8e2d5, 0.9, 0, { side: THREE.DoubleSide });
  var throwFb = mat(0x9a8f7c, 1);
  var beanFab = mat(0x8f8578, 1);

  // ---------- local helpers ----------
  function cyl(r0, r1, h, m, x, y, z) {
    var g = new THREE.Mesh(new THREE.CylinderGeometry(r0, r1, h, 16), m);
    g.position.set(x, y, z);
    g.castShadow = true; g.receiveShadow = true;
    house.add(g);
    return g;
  }
  // cable from cableTop down to shade, dark shade cylinder, warm inner disc
  function pendant(x, z, cableTop, shadeY, shadeR, shadeH, discR) {
    var top = shadeY + shadeH / 2;
    cyl(0.008, 0.008, cableTop - top, M.black, x, (cableTop + top) / 2, z);
    cyl(shadeR, shadeR, shadeH, shadeDk, x, shadeY, z);
    cyl(discR, discR, 0.015, warmIn, x, shadeY - shadeH / 2 + 0.01, z);
  }

  // ================= LIVING (LGF, y0=0) =================
  // L-shaped sofa facing the west TV wall (clear of D3 opening at z-5.355)
  box(-1.02, -0.30, 0, 0.42, -4.52, -1.28, sofaFab);          // main seat run
  box(-0.30, -0.06, 0, 0.82, -4.52, -1.28, sofaFab);          // back (east side)
  box(-1.02, -0.06, 0, 0.58, -1.28, -1.06, sofaFab);          // north arm
  box(-2.52, -1.02, 0, 0.42, -4.52, -3.72, sofaFab);          // chaise (L return)
  // cushions, slightly rotated
  var cush = [
    [-0.44, -4.15, 0.14], [-0.44, -3.55, -0.10], [-0.44, -2.90, 0.12],
